import{_ as a,o as t,c as o,a3 as s}from"./chunks/framework.DDx70NBX.js";const g=JSON.parse('{"title":"The web app","description":"","frontmatter":{},"headers":[],"relativePath":"docs/web-app.md","filePath":"docs/web-app.md"}'),n={name:"docs/web-app.md"};function i(r,e,h,d,c,l){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="the-web-app" tabindex="-1">The web app <a class="header-anchor" href="#the-web-app" aria-label="Permalink to &quot;The web app&quot;">​</a></h1><p>The web app is the signed-in website for members, at <code>app.coach-poulpy.com</code> (<a href="./adr/0021-the-landing-site-the-app-and-the-api-have-their-own-hostname">ADR 0021</a>). It is separate from <a href="./admin">the admin area</a>, which stays under <code>/admin</code>. The work is tracked in <a href="https://github.com/tkint/coach-poulpy/issues/355" target="_blank" rel="noreferrer">#355</a>.</p><h2 id="how-it-is-built" tabindex="-1">How it is built <a class="header-anchor" href="#how-it-is-built" aria-label="Permalink to &quot;How it is built&quot;">​</a></h2><ul><li><strong>The same stack as the admin</strong>: Vue and DaisyUI from <code>web/ui</code> (<a href="./adr/0023-the-websites-share-one-vue-and-daisyui-design-system">ADR 0023</a>). A missing component is added there, never styled in the app.</li><li><strong>The same sign-in as the admin</strong>: cookies from <code>POST /api/v1/web/session</code> (<a href="./the-api">the API</a>). The page never sees a token. Unlike the admin, any confirmed account may sign in.</li><li><strong>A sidebar</strong>, the admin&#39;s <code>CpDrawer</code> shell. It lists only the screens that exist; each feature adds its own entry. An <strong>Admin</strong> link to <code>/admin</code> sits at the bottom of the sidebar, just above the person, and appears only when <code>GET /api/v1/me</code> says the role is <code>admin</code>; a member never sees it, and the admin area still checks the role itself (<a href="./admin">the admin area</a>). The admin&#39;s sidebar has the matching <strong>Coach Poulpy app</strong> link back to <code>/</code>, in the same place.</li></ul><h2 id="navigation-lives-in-the-url" tabindex="-1">Navigation lives in the URL <a class="header-anchor" href="#navigation-lives-in-the-url" aria-label="Permalink to &quot;Navigation lives in the URL&quot;">​</a></h2><p>This holds for every screen of the websites, the web app and the admin.</p><ul><li><strong>Every screen has its own path.</strong> A sidebar entry is a real link (<code>&lt;a href&gt;</code>), so it opens in a new tab and a reload lands on the same screen. Clicking it navigates without reloading the page (<code>navigate</code> in <code>web/app/src/route.ts</code>), and the back button works.</li><li><strong>A screen keeps its state in the query string</strong>: a table&#39;s filters, sort and page, the open tab, the picked row. The address of a view can be copied, bookmarked and sent to someone, and the back button steps through the changes. A value equal to its default isn&#39;t written, so the plain address stays plain (<code>withParams</code>).</li><li><strong>A change a person made goes in as a new history entry; typing replaces the current one</strong>, so a search box doesn&#39;t fill the history with one entry per letter.</li><li><strong>The address is the one source of truth</strong>: the screen derives its state from it (<code>search</code>, <code>path</code>) and changes it with <code>navigate</code>, never a copy that can drift. A link to a row that is not on the loaded page loads that row itself.</li></ul><p>The admin&#39;s accounts table is the reference: <code>/admin/accounts?q=lea&amp;role=admin&amp;sort=email&amp;order=asc&amp;page=2&amp;account=&lt;id&gt;</code> (<a href="./admin#accounts">the admin area</a>).</p><h2 id="the-screens" tabindex="-1">The screens <a class="header-anchor" href="#the-screens" aria-label="Permalink to &quot;The screens&quot;">​</a></h2><p>They are agreed (see Mockups, Agreed, Web app on the site).</p><ul><li><strong>Sign in</strong> is the landing route. A person who is already signed in goes straight to the profile. A wrong email or password gets one message that doesn&#39;t say which. (<code>app-sign-in</code>, <code>app-sign-in-error</code>)</li><li><strong>Status</strong>, at <code>/status</code>, says whether Coach Poulpy is up or down and nothing else, for anyone, signed in or not; the admin has the details (<a href="./admin#status">Status</a>). (<code>app-status</code>, <code>app-status-down</code>)</li><li><strong>Profile</strong> shows the address and that the email is confirmed, a button that emails a password reset link, and a note that workouts and the body log live on the phone. It shows only what the server holds for the web: the profile fields stay on the phone, and <code>sync</code> is a scope of the apps (<a href="./accounts#sync">Accounts</a>). (<code>app-profile</code>)</li></ul><h2 id="not-yet" tabindex="-1">Not yet <a class="header-anchor" href="#not-yet" aria-label="Permalink to &quot;Not yet&quot;">​</a></h2><p>A &quot;Forgot your password?&quot; link on the sign-in page, the profile fields, workouts and sessions on the web.</p>',13)])])}const m=a(n,[["render",i]]);export{g as __pageData,m as default};
